      (
        (UPPER(`Customer Level Flag`) = UPPER('N'))
        AND (CAST(`Change Category` AS string) IN ('New Customer', 'Customer Reactivation', 'Existing Customer, New Product', 'Product Reactivation'))
      )
      AND (UPPER(Product) = UPPER('ReadyRosie')))
  )
  OR (
       (
         (
           (UPPER(`Customer Level Flag`) = UPPER('N'))
           AND (CAST(`Change Category` AS string) IN ('New Customer', 'Customer Reactivation', 'Existing Customer, New Product', 'Product Reactivation'))
         )
         AND (UPPER(Product) = UPPER('ReadyRosie'))
       ) IS NULL
